        placement = {g: [] for g in range(gpu_num)}
        rem = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for m in order:
            best, best_kvpr = None, float("inf")
            for g in range(gpu_num):
                if m.model_size <= rem[g] and rem[g] > 0:
                    kvpr = (load[g] + m.req_rate / m.slo) / (rem[g] - m.model_size)
                    if kvpr < best_kvpr:
                        best_kvpr, best = kvpr, g
            if best is None:
                return None, None, None
            placement[best].append(m)
            load[best] += m.req_rate / m.slo
            rem[best] -= m.model_size
        return placement, load, rem

    orders = [
        sorted(models, key=lambda x: x.req_rate / x.slo, reverse=True),
        sorted(models, key=lambda x: x.req_rate / x.slo),
        sorted(models, key=lambda x: x.model_size, reverse=True),
        sorted(models, key=lambda x: x.model_size),
    ]
    best_placement, best_load, best_rem, best_score = None, None, None, float("inf")
    for order in orders:
        p, load, rem = run(order)
        if p is not None:
            s = max(load[g] / rem[g] for g in range(gpu_num) if rem[g] > 0)
            if s < best_score:
                best_placement, best_load, best_rem, best_score = p, load, rem, s
    if best_placement is None:
        # FFD fallback: feasible whenever any placement exists
        best_placement = {g: [] for g in range(gpu_num)}
        best_rem = [GPU_MEM_SIZE] * gpu_num
        best_load = [0.0] * gpu_num
        for m in sorted(models, key=lambda x: x.model_size, reverse=True):
            for g in range(gpu_num):
                if m.model_size <= best_rem[g]:
                    best_placement[g].append(m)
                    best_load[g] += m.req_rate / m.slo
                    best_rem[g] -= m.model_size
                    break
            else:
                raise ValueError("Unable to place all models on any GPU")

    # Local search: move models out of the bottleneck GPU
    placement, load, rem = best_placement, best_load, best_rem
    for _ in range(500):
        k = [load[g] / rem[g] if rem[g] > 0 else float("inf") for g in range(gpu_num)]
        b = max(range(gpu_num), key=lambda g: k[g])
        improved = False
        for m in list(placement[b]):
            w = m.req_rate / m.slo
            for g in range(gpu_num):
                if g == b or m.model_size > rem[g]:
                    continue
                nb = (load[b] - w) / (rem[b] + m.model_size)
                ng = (load[g] + w) / (rem[g] - m.model_size)
                if max(nb, ng) < k[b] - 1e-12:
