def compute_model_placement(gpu_num, models):
    """Exact MILP approach: binary-search the max KVPR target T. For a
    fixed T, feasibility is linear: assign each model to exactly one GPU
    with sum_m (w_m + T*s_m) x[m,g] <= T*M per GPU. Solved with
    scipy.optimize.milp; falls back to greedy if unavailable."""
    placement = {g: [] for g in range(gpu_num)}
    if not models:
        return placement

    w = [m.req_rate / m.slo for m in models]
    s = [m.model_size for m in models]
    n, G = len(models), gpu_num

    def greedy():
        rem = [GPU_MEM_SIZE] * G
        pl = {g: [] for g in range(G)}
        for m in sorted(models, key=lambda x: x.model_size, reverse=True):
            for g in range(G):
                if m.model_size <= rem[g]:
                    pl[g].append(m)
                    rem[g] -= m.model_size
                    break
            else:
                raise ValueError("Unable to place all models on any GPU")
        return pl

    try:
        import numpy as np
        from scipy.optimize import milp, LinearConstraint, Bounds
        from scipy.sparse import lil_matrix

        def feasible(T):
            # vars: x[m,g]
            A = lil_matrix((n + G, n * G))
            for m in range(n):
                for g in range(G):
                    A[m, m * G + g] = 1.0
            for g in range(G):
                for m in range(n):
                    A[n + g, m * G + g] = w[m] + T * s[m]
            constraints = LinearConstraint(
                A.tocsr(),
                lb=np.r_[np.ones(n), np.full(G, -np.inf)],
                ub=np.r_[np.full(n, 1.0), np.full(G, T * GPU_MEM_SIZE)],
            )
            res = milp(
                c=np.zeros(n * G),
                constraints=constraints,
                integrality=np.ones(n * G),
                bounds=Bounds(0, 1),
            )
            if not res.success:
                return None
            x = np.round(res.x).astype(int)
            pl = {g: [] for g in range(G)}
            for m in range(n):
                pl[int(np.argmax(x[m * G:(m + 1) * G]))].append(models[m])
            return pl

        lo, hi = 1e-9, max(sum(w) / max(GPU_MEM_SIZE - min(s), 1e-9), 1e-3) * G + 10.0
        best = None
        for _ in range(40):
            mid = 0.5 * (lo + hi)
            sol = feasible(mid)
            if sol is not None:
                best, hi = sol, mid
            else:
                lo = mid
        if best is not None:
            return best
    except Exception:
        pass
    return greedy()


