def compute_model_placement(gpu_num, models):
    """
    Compute a model placement that minimizes the maximum KVPR across all GPUs.

    Args:
        gpu_num: Number of GPUs
        models: List of models to place

    Returns:
        A placement of models to GPUs
    """

    """Greedy placement over multiple orderings + local search.

    Phase 1: for each ordering, greedily assign each model to the GPU
    minimizing its KVPR after placement; keep the best result. A
    first-fit-decreasing fallback guarantees feasibility. Phase 2:
    local search repeatedly moves a model from the max-KVPR GPU or swaps
    two models whenever it strictly lowers max KVPR and fits in memory.
    """
    def feasible_pack():
        """First-fit-decreasing by size: always feasible if any packing is."""
        placement = {g: [] for g in range(gpu_num)}
        rem = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for m in sorted(models, key=lambda x: x.model_size, reverse=True):
            w = m.req_rate / m.slo
            for g in range(gpu_num):
                if m.model_size <= rem[g]:
                    placement[g].append(m)
                    load[g] += w
                    rem[g] -= m.model_size
                    break
            else:
                return None, None, None
        return placement, rem, load
    def run(order):
        placement = {g: [] for g in range(gpu_num)}
        rem = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for m in order:
            best, best_kvpr = None, float("inf")
            for g in range(gpu_num):
                if m.model_size <= rem[g]:
                    kvpr = (load[g] + m.req_rate / m.slo) / (rem[g] - m.model_size)
                    if kvpr < best_kvpr:
                        best_kvpr, best = kvpr, g
            if best is None:
                return None, float("inf")
            placement[best].append(m)
            load[best] += m.req_rate / m.slo
            rem[best] -= m.model_size
        return placement, rem, load

    def score(rem, load):
        return max(load[g] / rem[g] for g in range(gpu_num))

    def kvpr_after(rem, load, src, dst, m):
        """Max KVPR if model m moves from src to dst."""
        w, s = m.req_rate / m.slo, m.model_size
        return max(
            (load[g] - (w if g == src else 0) + (w if g == dst else 0))
            / (rem[g] + (s if g == src else 0) - (s if g == dst else 0))
            for g in range(gpu_num))

    def apply_move(placement, rem, load, src, dst, m):
        w, s = m.req_rate / m.slo, m.model_size
        placement[src].remove(m); placement[dst].append(m)
        load[src] -= w; load[dst] += w
        rem[src] += s; rem[dst] -= s

    def local_search(placement, rem, load):
        cur = score(rem, load)
        improved = True
        while improved:
            improved = False
            src = max(range(gpu_num), key=lambda g: load[g] / rem[g])
            for m in list(placement[src]):
                for dst in range(gpu_num):
                    if dst == src or m.model_size > rem[dst]:
                        continue
                    new_max = kvpr_after(rem, load, src, dst, m)
                    if new_max < cur - 1e-12:
                        apply_move(placement, rem, load, src, dst, m)
                        cur, improved = new_max, True
                        break
                if improved:
                    break
            if improved:
                continue
            # Try swaps between the bottleneck GPU and others.
            for a in list(placement[src]):
                for dst in range(gpu_num):
                    if dst == src:
                        continue
                    for b in list(placement[dst]):
                        sa, sb = a.model_size, b.model_size
                        if sb > rem[src] + sa or sa > rem[dst] + sb:
                            continue
                        # Tentatively swap
                        apply_move(placement, rem, load, src, dst, a)
                        apply_move(placement, rem, load, dst, src, b)
                        new_max = score(rem, load)
                        if new_max < cur - 1e-12:
                            cur, improved = new_max, True
                            break
                        # Undo
                        apply_move(placement, rem, load, src, dst, b)
                        apply_move(placement, rem, load, dst, src, a)
                    if improved:
                        break
                if improved:
                    break
        return placement, cur

    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.model_size),
        sorted(models, key=lambda m: m.req_rate / m.slo / m.model_size, reverse=True),
        sorted(models, key=lambda m: m.model_size / (m.req_rate / m.slo)),
    ]
    best_placement, best_score = None, float("inf")
    for order in orders:
        p, rem, load = run(order)
        if p is None:
            continue
        p, s = local_search(p, rem, load)
        if s < best_score:
            best_placement, best_score = p, s
    if best_placement is None:
        best_placement, rem, load = feasible_pack()
        if best_placement is None:
            raise ValueError("Unable to place all models on any GPU")
        best_placement, best_score = local_search(best_placement, rem, load)
    return best_placement


