def compute_model_placement(gpu_num, models):
    """Bisection search on KVPR threshold T with bin-packing feasibility test.

    The per-GPU constraint load[g] <= T*(S - mem[g]) rewrites exactly as
    sum(w_i + T*s_i for models on g) <= T*S, i.e. bin packing where each
    model has cost c_i = w_i + T*s_i and every bin has capacity T*S.
    For a candidate T we test feasibility with first-fit-decreasing over a
    couple of item orderings; binary search then finds the minimal feasible
    T. Falls back to plain first-fit-decreasing if packing ever fails."""
    if not models:
        return {g: [] for g in range(gpu_num)}
    S = GPU_MEM_SIZE
    w = [m.req_rate / m.slo for m in models]
    s = [m.model_size for m in models]

    def pack(order, cap):
        bins = [0.0] * gpu_num
        assign = []
        for i in order:
            if s[i] > S:
                return None
            for g in range(gpu_num):
                if bins[g] + w[i] + cap * s[i] <= cap * S + 1e-9:
                    bins[g] += w[i] + cap * s[i]
                    assign.append((i, g))
                    break
            else:
                return None
        placement = {g: [] for g in range(gpu_num)}
        for i, g in assign:
            placement[g].append(models[i])
        return placement

    total_w = sum(w)
    hi = total_w / max(S - sum(s) / gpu_num, 1e-9) * gpu_num + 1.0
    orders = [sorted(range(len(models)), key=lambda i: -(w[i] + s[i])),
              sorted(range(len(models)), key=lambda i: -w[i]),
              sorted(range(len(models)), key=lambda i: -s[i])]
    lo, best = 0.0, None
    for _ in range(40):
        mid = (lo + hi) / 2
        for o in orders:
            p = pack(o, mid)
            if p is not None:
                best, hi = p, mid
                break
        else:
            lo = mid
    if best is None:
        best = pack(sorted(range(len(models)), key=lambda i: -s[i]), 1e9)
        if best is None:
            best = {g: [] for g in range(gpu_num)}
    return best


